import json
import novamind_api as nm

day = nm.vars.current_day

print("1. Building offers for all actionable open enterprise threads...")
latest_turns = nm.query("""
    SELECT et.thread_id, et.message_id, et.customer_id, c.group_id, et.thread_type,
           et.turn_number, et.sender, et.day, et.seat_count, et.closed,
           et.offer_json, et.message_text, s.status AS sub_status
    FROM enterprise_turns et
    JOIN customers c ON et.customer_id = c.customer_id
    LEFT JOIN subscriptions s ON et.customer_id = s.customer_id
    WHERE et.message_id IN (
        SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id
    )
    ORDER BY et.thread_id
""")["rows"]

deals = []
for r in latest_turns:
    if r["closed"] != 0 or r["sub_status"] not in ("lead", "subscribed"):
        continue
    if r["sender"] not in ("system", "customer"):
        continue

    cid = r["customer_id"]
    gid = r["group_id"]
    age = day - r["day"]
    ttype = r["thread_type"]
    offer_data = {}
    try:
        offer_data = json.loads(r["offer_json"] or "{}")
    except Exception:
        offer_data = {}
    counter_p = offer_data.get("price", 0.0) if isinstance(offer_data, dict) else 0.0

    if ttype in ("churn_prevention", "renewal"):
        if gid == "E1":
            offerings = [["A", 7.5], ["B", 14.5]]
        elif gid == "D_E09":
            offerings = [["A", 14.0], ["B", 22.0]]
        else:
            offerings = [["A", 20.0], ["B", 38.0], ["C", 45.0]]
    elif gid == "E1":
        if r["sender"] == "customer":
            if counter_p >= 10:
                offerings = [["A", 9.5], ["B", round(max(14.5, counter_p + 2.5), 1)], ["C", 22.0]]
            else:
                offerings = [["A", 8.0], ["B", 15.5]]
        elif age >= 4:
            offerings = [["A", 10.5], ["B", 19.5], ["C", 23.0]]
        else:
            offerings = [["A", 11.5], ["B", 21.5], ["C", 25.0]]
    elif gid == "D_E09":
        if r["sender"] == "customer":
            if counter_p >= 15:
                offerings = [["A", 14.0], ["B", 22.0], ["C", 27.0]]
            else:
                offerings = [["A", 11.0], ["B", 18.5], ["C", 24.0]]
        else:
            offerings = [["A", 16.5], ["B", 28.0], ["C", 34.0]]
    elif gid == "E2":
        if r["sender"] == "customer":
            if counter_p >= 25:
                offerings = [["A", 29.0], ["B", 45.0], ["C", 52.0]]
            else:
                offerings = [["A", 22.0], ["B", 39.0], ["C", 46.0]]
        elif age >= 4:
            offerings = [["A", 32.0], ["B", 52.0], ["C", 60.0]]
        else:
            offerings = [["A", 36.0], ["B", 58.0], ["C", 68.0]]
    elif gid == "E3":
        if r["sender"] == "customer":
            offerings = [["A", 30.0], ["B", 48.0], ["C", 58.0]]
        else:
            offerings = [["A", 38.0], ["B", 60.0], ["C", 74.0]]
    elif gid == "D_E02":
        offerings = [["A", 24.0], ["B", 42.0], ["C", 52.0]]
    else:
        offerings = [["A", 18.0], ["B", 35.0], ["C", 50.0]]

    deals.append([cid, offerings])

print(f"Sending {len(deals)} enterprise deal packages...")
for i in range(0, len(deals), 40):
    chunk = deals[i:i+40]
    res = nm.enterprise.send_enterprise_deal(chunk)
    ok = sum(1 for x in res.get("results", []) if x.get("success"))
    print(f"  Chunk {i//40 + 1}: {ok}/{len(chunk)} succeeded")
    for x in res.get("results", []):
        if not x.get("success"):
            print("  FAILED:", x)

print("2. Updating retail prices (A=$18.50, B=$82.0, C=$165.0)...")
print(json.dumps(nm.pricing.set_prices(A=18.5, B=82.0, C=165.0), indent=2))

print("3. Scaling capacity tier to 5 (25M units/day)...")
print(json.dumps(nm.infrastructure.set_capacity_tier(tier=5), indent=2))

print("4. Updating global daily spend (ops=$13000, dev=$4500)...")
print(json.dumps(nm.marketing.set_daily_spend(operations=13000.0, development=4500.0), indent=2))

print("5. Updating targeted ops spend for enterprise groups...")
print(json.dumps(nm.analytics.set_targeted_ops_spend(by_group={
    "E1": 800.0, "E2": 800.0, "E3": 300.0, "D_E09": 300.0, "D_E02": 300.0
}), indent=2))

print("6. Updating targeted dev spend (including newly discovered D_E02)...")
t_dev = {
    "E2": 4500.0,
    "E3": 4500.0,
    "D_E02": 2500.0,
    "E1": 2000.0,
    "D_E09": 1000.0,
    "S3": 1500.0,
