    "S1": 500.0,
}
print(json.dumps(nm.analytics.set_targeted_dev_spend(t_dev), indent=2))

print("7. Scaling targeted ad spend to $26,000/day...")
t_ads = {
    "content_marketing": {"S1": 3200.0, "S2": 6200.0, "S3": 2000.0},
    "referral_program": {"S1": 2800.0, "S2": 1800.0, "S3": 4800.0},
    "linkedin": {"S2": 3200.0},
    "social_media": {"S3": 2000.0},
}
print(json.dumps(nm.marketing.set_targeted_ad_spend(t_ads), indent=2))

print("8. Posting 25B token/day GPU expansion & academic/enterprise compliance update...")
