    content="Expanded NovaMind cluster capacity to 25B tokens/day with zero downtime, FERPA/SOC2 institutional workspaces, and <24h dedicated engineering SLA—proven 3x productivity at half the TCO."
)
print(json.dumps(post_res, indent=2))

