import json
import novamind_api as nm

day = nm.vars.current_day

print("1. Querying and replying to all actionable open enterprise threads...")
latest_turns = nm.query("""
    SELECT et.thread_id, et.message_id, et.customer_id, c.group_id, et.thread_type,
           et.turn_number, et.sender, et.day, et.seat_count, et.closed,
           et.offer_json, et.message_text, s.status AS sub_status
    FROM enterprise_turns et
    JOIN customers c ON et.customer_id = c.customer_id
    LEFT JOIN subscriptions s ON et.customer_id = s.customer_id
    WHERE et.message_id IN (
        SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id
    )
    ORDER BY et.thread_id
""")["rows"]

deals = []
for r in latest_turns:
    if r["closed"] != 0 or r["sub_status"] not in ("lead", "subscribed"):
        continue
    if r["sender"] not in ("system", "customer"):
        continue

    cid = r["customer_id"]
    gid = r["group_id"]
    age = day - r["day"]
    ttype = r["thread_type"]
    offer_data = {}
    try:
        offer_data = json.loads(r["offer_json"] or "{}")
    except Exception:
        offer_data = {}
    counter_p = offer_data.get("price", 0.0) if isinstance(offer_data, dict) else 0.0

    if ttype in ("churn_prevention", "renewal"):
        if gid == "E1":
            offerings = [["A", 7.5], ["B", 13.5]]
        elif gid == "D_E09":
            offerings = [["A", 8.5], ["B", 15.5]]
        elif gid == "E2":
            offerings = [["A", 22.0], ["B", 38.0], ["C", 46.0]]
        elif gid == "E3":
            offerings = [["A", 28.0], ["B", 45.0], ["C", 55.0]]
        else:
            offerings = [["A", 18.0], ["B", 32.0], ["C", 42.0]]
    elif gid == "E1":
        if r["sender"] == "customer":
            if counter_p >= 10:
                offerings = [["A", 9.5], ["B", round(max(14.5, counter_p + 2.0), 1)], ["C", 22.0]]
            else:
                offerings = [["A", 8.0], ["B", 15.0]]
        elif age >= 4:
            offerings = [["A", 10.5], ["B", 19.5], ["C", 23.0]]
        else:
            offerings = [["A", 11.5], ["B", 21.0], ["C", 25.0]]
    elif gid == "D_E09":
        if r["sender"] == "customer":
            if counter_p >= 15:
                offerings = [["A", 14.0], ["B", 23.0], ["C", 28.0]]
            else:
                offerings = [["A", 10.5], ["B", 18.0], ["C", 24.0]]
        else:
            offerings = [["A", 16.0], ["B", 27.0], ["C", 34.0]]
    elif gid == "E2":
        if r["sender"] == "customer":
            if counter_p >= 30:
                offerings = [["A", 28.0], ["B", round(max(43.0, counter_p + 5.0), 1)], ["C", 55.0]]
            elif counter_p >= 15:
                offerings = [["A", 24.0], ["B", 38.0], ["C", 46.0]]
            else:
                offerings = [["A", 19.0], ["B", 34.0], ["C", 42.0]]
        elif age >= 4:
            offerings = [["A", 36.0], ["B", 56.0], ["C", 66.0]]
        else:
            offerings = [["A", 40.0], ["B", 62.0], ["C", 72.0]]
    elif gid == "E3":
        if r["sender"] == "customer":
            if counter_p >= 35:
                offerings = [["A", 32.0], ["B", round(max(46.0, counter_p + 6.0), 1)], ["C", 60.0]]
            else:
                offerings = [["A", 26.0], ["B", 44.0], ["C", 55.0]]
        elif age >= 4:
            offerings = [["A", 40.0], ["B", 60.0], ["C", 74.0]]
        else:
            offerings = [["A", 44.0], ["B", 66.0], ["C", 80.0]]
    elif gid == "D_E02":
        if r["sender"] == "customer":
            offerings = [["A", 14.0], ["B", 24.0], ["C", 30.0]]
        else:
            offerings = [["A", 22.0], ["B", 36.0], ["C", 46.0]]
    elif gid in ("D_E08", "D_E07"):
        if r["sender"] == "customer":
            offerings = [["A", 30.0], ["B", round(max(48.0, counter_p + 8.0), 1)], ["C", 62.0]]
        else:
            offerings = [["A", 45.0], ["B", 72.0], ["C", 88.0]]
    else:
        offerings = [["A", 20.0], ["B", 38.0], ["C", 52.0]]

    deals.append([cid, offerings])

print(f"Sending {len(deals)} enterprise deal packages...")
for i in range(0, len(deals), 80):
    chunk = deals[i:i+80]
    res = nm.enterprise.send_enterprise_deal(chunk)
    ok = sum(1 for x in res.get("results", []) if x.get("success"))
    print(f"  Chunk {i//80 + 1}: {ok}/{len(chunk)} succeeded")
    for x in res.get("results", []):
        if not x.get("success"):
            print("  FAILED:", x)

print("2. Updating retail prices (A=$19.50, B=$89.0, C=$175.0)...")
print(json.dumps(nm.pricing.set_prices(A=19.5, B=89.0, C=175.0), indent=2))

print("3. Scaling capacity tier to 6 (80M units/day)...")
print(json.dumps(nm.infrastructure.set_capacity_tier(tier=6), indent=2))

print("4. Updating global daily spend (ops=$28000, dev=$6000)...")
print(json.dumps(nm.marketing.set_daily_spend(operations=28000.0, development=6000.0), indent=2))

print("5. Updating targeted ops spend...")
print(json.dumps(nm.analytics.set_targeted_ops_spend(by_group={
    "E1": 2500.0, "E2": 3000.0, "E3": 1200.0, "D_E09": 600.0,
    "D_E02": 600.0, "D_E08": 400.0, "D_E07": 400.0
}), indent=2))

print("6. Updating targeted dev spend...")
t_dev = {
    "D_E08": 4000.0,
    "D_E07": 4000.0,
    "D_E02": 3500.0,
    "D_S07": 3500.0,
    "D_S04": 2500.0,
    "D_S10": 2000.0,
    "D_S06": 1500.0,
    "E3": 2500.0,
    "E2": 1500.0,
    "S3": 1000.0,
}
print(json.dumps(nm.analytics.set_targeted_dev_spend(t_dev), indent=2))

print("7. Scaling targeted ad spend to $40,650/day...")
t_ads = {
    "content_marketing": {
        "S1": 4500.0, "S2": 9500.0, "S3": 2800.0, "D_S10": 1000.0,
        "D_S04": 50.0, "D_S06": 50.0, "D_S03": 50.0
    },
    "referral_program": {
        "S1": 3800.0, "S2": 2600.0, "S3": 7000.0, "D_S07": 400.0,
        "D_S04": 50.0, "D_S06": 50.0, "D_S03": 50.0
    },
    "linkedin": {
        "S2": 4800.0, "D_S10": 600.0, "D_S07": 300.0,
        "D_S04": 50.0, "D_S06": 50.0, "D_S03": 50.0
    },
    "social_media": {
        "S3": 2600.0,
        "D_S04": 50.0, "D_S06": 50.0, "D_S03": 50.0
    },
    "search_ads": {
        "D_S04": 50.0, "D_S06": 50.0, "D_S03": 50.0
    },
}
print(json.dumps(nm.marketing.set_targeted_ad_spend(t_ads), indent=2))

print("8. Posting 80B token/day hyperscale cluster & Telecom/Agency suite announcement...")
post_res = nm.marketing.post_social_media(
    content="NovaMind Hyperscale Cluster now live at 80B tokens/day: sub-200ms P95 across 110,000+ seats, carrier-grade Telecom & Fortune-500 SLAs, and multi-project Agency workspaces."
)
print(json.dumps(post_res, indent=2))

